  // ── Planting techniques (data/binalonan.ts) ──
  // Names/descriptions/tags are translated here; the underlying English
  // strings in binalonan.ts stay as the canonical ids used for storage
  // and yield-model lookups (TECHNIQUE_BONUS, seed-rate tables, etc).
  "technique.transplanting.name": { en: "Transplanting (Pindot)", tl: "Paglilipat-tanim (Pindot)", ilo: "Panagmula manipud iti nursery (Pindot)" },
  "technique.transplanting.desc": { en: "Raise seedlings in a nursery for 20–25 days, then transplant 2–3 seedlings per hill at 20×20 cm spacing. Best for wet-season fields with consistent water supply.", tl: "Magpalaki ng punla sa nursery nang 20–25 araw, pagkatapos ay ilipat 2–3 punla kada puwang na may 20×20 cm na agwat. Pinakamainam sa taniman tuwing tag-ulan na may tuloy-tuloy na suplay ng tubig.", ilo: "Padakkelen dagiti mula iti nursery iti 20–25 nga aldaw, kalpasanna ket iyalis ti 2–3 nga mula iti tunggal abut nga adda 20×20 cm nga distansia. Kasayaatan para kadagiti talon iti tiempo ti tudo nga adda kanayon nga danum." },
  "technique.wetDirectSeeding.name": { en: "Wet Direct Seeding (Sabog-Tanim)", tl: "Direktang Pagtatanim sa Basang Lupa (Sabog-Tanim)", ilo: "Direkta a Panagmula iti Nabasa a Daga (Sabog-Tanim)" },
  "technique.wetDirectSeeding.desc": { en: "Pre-germinate seeds for 24–48 hours then broadcast directly onto puddled soil. Reduces labor cost and speeds establishment in high-rainfall areas.", tl: "Pausbungin muna ang binhi nang 24–48 oras bago ikalat nang direkta sa binasang lupa. Nagpapababa ng gastos sa paggawa at nagpapabilis ng paglago sa lugar na maulan.", ilo: "Pasukogan pay laeng dagiti bukel iti 24–48 nga oras sana ikalap direkta iti nabasa a daga. Umbasit ti gastos ti panagtrabaho ken pumardas ti panagtubo kadagiti lugar nga adu ti tudo." },
  "technique.dryDirectSeeding.name": { en: "Dry Direct Seeding (Sabog-Tanim)", tl: "Direktang Pagtatanim sa Tuyong Lupa (Sabog-Tanim)", ilo: "Direkta a Panagmula iti Namaga a Daga (Sabog-Tanim)" },
  "technique.dryDirectSeeding.desc": { en: "Sow pre-soaked seeds into moist soil using a seed drill at 25–30 kg/ha seeding rate. Saves water and is ideal for dry-season planting or drought-prone barangays.", tl: "Ihasik ang nababad na binhi sa basa-basang lupa gamit ang seed drill sa rate na 25–30 kg/ha. Nakakatipid ng tubig at mainam para sa tag-tuyot na pagtatanim.", ilo: "Imulam dagiti nabasa nga bukel iti nabasa a daga nga usaren ti seed drill iti 25–30 kg/ha a rate. Mangisalakan iti danum ken kasayaatan para iti panagmula iti panawen ti tikag." },
  "technique.sri.name": { en: "System of Rice Intensification (SRI)", tl: "Sistema ng Intensipikasyon ng Palay (SRI)", ilo: "Sistema ti Panangpabaknang iti Pagay (SRI)" },
  "technique.sri.desc": { en: "Plant single young seedlings (8–12 days) at wider spacing (25×25 cm). Use intermittent irrigation instead of continuous flooding. Increases yield by 20–30% with less water.", tl: "Magtanim ng iisang murang punla (8–12 araw) na may mas malawak na agwat (25×25 cm). Gumamit ng patalinghagang patubig sa halip na tuluy-tuloy na pagbaha. Nagpapataas ng ani ng 20–30% na may mas kaunting tubig.", ilo: "Imulam ti sangsangkabassit nga ubbing a mula (8–12 nga aldaw) nga adda nalawa a distansia (25×25 cm). Usaren ti sisasaad a pannakadanum imbes a agtultuloy a panagbaha. Umadu ti apit iti 20–30% nga bassit laeng ti danum a maus-usar." },
  "technique.hillPlanting.name": { en: "Hill Planting", tl: "Pagtatanim sa Puwang", ilo: "Panagmula iti Abut" },
  "technique.hillPlanting.desc": { en: "Plant 2–3 seeds per hill at 75×25 cm spacing (rows × hills). Thin to 1 plant per hill after emergence. Standard method for Binalonan upland plots.", tl: "Magtanim ng 2–3 buto kada puwang na may 75×25 cm na agwat (hanay × puwang). Bawasan sa 1 halaman kada puwang pagkatapos sumibol. Karaniwang paraan sa mga taniman sa itaas ng Binalonan.", ilo: "Imulam ti 2–3 a bukel iti tunggal abut nga adda 75×25 cm nga distansia (linia × abut). Bassitan iti 1 a mula iti tunggal abut kalpasan ti panagrusing. Kadawyan a wagas para kadagiti taltalon iti nangato a paset ti Binalonan." },
  "technique.rowPlanting.name": { en: "Row Planting (Furrow Method)", tl: "Pagtatanim sa Hanay (Paraang Bukal)", ilo: "Panagmula iti Linia (Wagas ti Kanal)" },
  "technique.rowPlanting.desc": { en: "Open furrows 75 cm apart, drop seeds every 25 cm, then cover. Allows mechanized cultivation between rows and better water infiltration for clay loam soils.", tl: "Gumawa ng bukal na may 75 cm na agwat, maglagay ng buto tuwing 25 cm, pagkatapos ay takpan. Nagbibigay-daan sa makinaryang pagsasaka sa gitna ng hanay at mas mahusay na pagsipsip ng tubig sa lupang clay loam.", ilo: "Mangaramid ti kanal nga adda 75 cm a distansia, ikabil ti bukel iti tunggal 25 cm, kalpasanna ket kalubam. Mabalin ti panagusar ti makina iti nagbaetan dagiti linia ken nasaysayaat a pannakasped ti danum iti clay loam a daga." },
  "technique.stripCropping.name": { en: "Strip Cropping with Legumes", tl: "Pagsasabay-tanim ng Legumbre", ilo: "Panagmula ti Legumbre a Naisallesep" },
  "technique.stripCropping.desc": { en: "Alternate 4–6 rows of corn with 2 rows of mungbean or cowpea. Legumes fix nitrogen, reduce erosion, and add a secondary income stream during the dry cycle.", tl: "Isalitan ang 4–6 na hanay ng mais sa 2 hanay ng mungo o sitaw. Nagdaragdag ang legumbre ng nitrogen sa lupa, nagpapababa ng erosyon, at nagdaragdag ng karagdagang kita tuwing tag-tuyot.", ilo: "Isallesep ti 4–6 a linia ti mais iti 2 a linia ti mungo wenno utong. Mangnayon ti nitrogen dagiti legumbre iti daga, umbasit ti erosion, ken mangnayon iti sabali a pagsapulan iti panawen ti tikag." },
  "technique.contourFarming.name": { en: "Contour Farming", tl: "Pagsasaka sa Kontorno", ilo: "Panagtalon iti Kontorno" },
  "technique.contourFarming.desc": { en: "Plant rows along the contour lines of sloping land to slow runoff. Combine with vegetative strips every 5 meters to prevent soil erosion during heavy rain months.", tl: "Magtanim ng hanay sa gilid ng dalisdis upang bagalan ang pag-agos ng tubig. Isama ang halamang panakip lupa tuwing 5 metro upang maiwasan ang erosyon tuwing malakas ang ulan.", ilo: "Imulam dagiti linia iti igid ti sardeng a daga tapno bumaggak ti panagayus ti danum. Itiponen ti mula a mangsalaknib iti daga iti tunggal 5 metro tapno maliklikan ti erosion iti panawen ti napigsa a tudo." },

