export function translate(lang: Lang, key: string, params?: Record<string, string | number>): string {
  const e = DICT[key];
  let out = e ? (e[lang] ?? e.en) : key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      out = out.replace(new RegExp(`\\{${k}\\}`, "g"), String(v));
    }
  }
  return out;
}

// Hook that returns a translator bound to the current interface language.
// Accepts an optional params map for keys with {placeholder} tokens, e.g.
// t("technique.cond.bestAtRainfall", { rainfall: 150 }).
export function useT() {
  const { lang } = useStore();
  return (key: string, params?: Record<string, string | number>) => translate(lang, key, params);
}
